ifact_versions","type":"f"},{"condeferrable":false,"condeferred":false,"conname":"editorial_artifact_versions_origin_check","convalidated":true,"definition":"CHECK (char_length(btrim(origin)) > 0)","table_name":"editorial_artifact_versions","type":"c"},{"condeferrable":false,"condeferred":false,"conname":"editorial_artifact_versions_payload_check","convalidated":true,"definition":"CHECK (jsonb_typeof(payload) = 'object'::text)","table_name":"editorial_artifact_versions","type":"c"},{"condeferrable":false,"condeferred":false,"conname":"editorial_artifact_versions_pkey","convalidated":true,"definition":"PRIMARY KEY (version_id)","table_name":"editorial_artifact_versions","type":"p"},{"condeferrable":false,"condeferred":false,"conname":"editorial_artifact_versions_previous_version_id_fkey","convalidated":true,"definition":"FOREIGN KEY (previous_version_id) REFERENCES editorial_artifact_versions(version_id) ON DELETE RESTRICT","table_name":"editorial_artifact_versions","type":"f"},{"condeferrable":false,"condeferred":false,"conname":"editorial_artifact_versions_source_version_id_fkey","convalidated":true,"definition":"FOREIGN KEY (source_version_id) REFERENCES editorial_artifact_versions(version_id) ON DELETE RESTRICT","table_name":"editorial_artifact_versions","type":"f"},{"condeferrable":false,"condeferred":false,"conname":"editorial_artifact_versions_status_check","convalidated":true,"definition":"CHECK (char_length(btrim(status)) >= 1 AND char_length(btrim(status)) <= 80)","table_name":"editorial_artifact_versions","type":"c"},{"condeferrable":false,"condeferred":false,"conname":"editorial_artifact_versions_version_number_check","convalidated":true,"definition":"CHECK (version_number > 0)","table_name":"editorial_artifact_versions","type":"c"},{"condeferrable":false,"condeferred":false,"conname":"editorial_version_status_events_actor_id_fkey","convalidated":true,"definition":"FOREIGN KEY (actor_id) REFERENCES auth.users(id) ON DELETE RESTRICT","table_name":"editorial_version_status_events","type":"f"},{"condeferrable":false,"condeferred":false,"conname":"editorial_version_status_events_pkey","convalidated":true,"definition":"PRIMARY KEY (id)","table_name":"editorial_version_status_events","type":"p"},{"condeferrable":false,"condeferred":false,"conname":"editorial_version_status_events_reason_check","convalidated":true,"definition":"CHECK (char_length(btrim(reason)) > 0)","table_name":"editorial_version_status_events","type":"c"},{"condeferrable":false,"condeferred":false,"conname":"editorial_version_status_events_status_check","convalidated":true,"definition":"CHECK (status = ANY (ARRAY['draft'::text, 'proposed'::text, 'approved'::text, 'rejected'::text, 'superseded'::text]))","table_name":"editorial_version_status_events","type":"c"},{"condeferrable":false,"condeferred":false,"conname":"editorial_version_status_events_version_id_fkey","convalidated":true,"definition":"FOREIGN KEY (version_id) REFERENCES editorial_artifact_versions(version_id) ON DELETE RESTRICT","table_name":"editorial_version_status_events","type":"f"}],"indexes":[{"definition":"CREATE INDEX editorial_artifact_versions_brand_lookup_idx ON public.editorial_artifact_versions USING btree (marca_id, artifact_type, entity_id, version_number DESC)","index_name":"editorial_artifact_versions_brand_lookup_idx","table_name":"editorial_artifact_versions"},{"definition":"CREATE UNIQUE INDEX editorial_artifact_versions_identity_unique ON public.editorial_artifact_versions USING btree (marca_id, artifact_type, entity_id, version_number)","index_name":"editorial_artifact_versions_identity_unique","table_name":"editorial_artifact_versions"},{"definition":"CREATE UNIQUE INDEX editorial_artifact_versions_pkey ON public.editorial_artifact_versions USING btree (version_id)","index_name":"editorial_artifact_versions_pkey","table_name":"editorial_artifact_versions"},{"definition":"CREATE INDEX editorial_version_status_events_actor_idx ON public.editorial_version_status_events USING btree (actor_id)","index_name":"editorial_version_status_events_actor_idx","table_name":"editorial_version_status_events"},{"definition":"CREATE UNIQUE INDEX editorial_version_status_events_pkey ON public.editorial_version_status_events USING btree (id)","index_name":"editorial_version_status_events_pkey","table_name":"editorial_version_status_events"},{"definition":"CREATE INDEX editorial_version_status_events_version_idx ON public.editorial_version_status_events USING btree (version_id, occurred_at DESC)","index_name":"editorial_version_status_events_version_idx","table_name":"editorial_version_status_events"}],"owners":[{"owner":"postgres","table_name":"editorial_artifact_versions"},{"owner":"postgres","table_name":"editorial_version_status_events"}],"policies":[{"cmd":"SELECT","permissive":"PERMISSIVE","policyname":"editorial_artifact_versions_select_policy","roles":["authenticated"],"table_name":"editorial_artifact_versions","using_expression":"canonical_actor_can_access_brand(marca_id, auth.uid())","with_check_expression":null},{"cmd":"SELECT","permissive":"PERMISSIVE","policyname":"editorial_version_status_events_select_policy","roles":["authenticated"],"table_name":"editorial_version_status_events","using_expression":"(EXISTS ( SELECT 1\n   FROM editorial_artifact_versions artifact\n  WHERE ((artifact.version_id = editorial_version_status_events.version_id) AND canonical_actor_can_access_brand(artifact.marca_id, ( SELECT auth.uid() AS uid)))))","with_check_expression":null}],"rls":[{"enabled":true,"forced":false,"table_name":"editorial_artifact_versions"},{"enabled":true,"forced":false,"table_name":"editorial_version_status_events"}],"target_constraints":[{"definition":"CHECK (artifact_type = ANY (ARRAY['article_dna'::text, 'silo_dna'::text, 'silo_page'::text, 'content_plan'::text, 'brand_dna'::text]))"}],"triggers":[{"definition":"CREATE TRIGGER editorial_artifact_versions_append_only_trg BEFORE DELETE OR UPDATE ON editorial_artifact_versions FOR EACH ROW EXECUTE FUNCTION pipeline_editorial_protect_append_only()","enabled":"O","function_definition":"CREATE OR REPLACE FUNCTION public.pipeline_editorial_protect_append_only()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\r\nBEGIN\r\n  RAISE EXCEPTION 'append-only editorial record cannot be changed';\r\nEND;\r\n$function$\n","function_name":"pipeline_editorial_protect_append_only()","table_name":"editorial_artifact_versions","tgname":"editorial_artifact_versions_append_only_trg"},{"definition":"CREATE TRIGGER editorial_artifact_versions_source_trg BEFORE INSERT OR UPDATE OF artifact_type, source_version_id, marca_id ON editorial_artifact_versions FOR EACH ROW EXECUTE FUNCTION pipeline_editorial_validate_artifact_source()","enabled":"O","function_definition":"CREATE OR REPLACE FUNCTION public.pipeline_editorial_validate_artifact_source()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\r\nDECLARE\r\n  source_type text;\r\n  source_brand uuid;\r\nBEGIN\r\n  IF NEW.artifact_type = 'silo_page' THEN\r\n    IF NEW.source_version_id IS NULL THEN\r\n      RAISE EXCEPTION 'silo_page requires a source SiloDNA version';\r\n    END IF;\r\n\r\n    SELECT artifact_type, marca_id\r\n      INTO source_type, source_brand\r\n    FROM public.editorial_artifact_versions\r\n    WHERE version_id = NEW.source_version_id;\r\n\r\n    IF source_type IS DISTINCT FROM 'silo_dna' OR source_brand IS DISTINCT FROM NEW.marca_id THEN\r\n      RAISE EXCEPTION 'silo_page source must be a SiloDNA version from the same Brand';\r\n    END IF;\r\n  END IF;\r\n\r\n  RETURN NEW;\r\nEND;\r\n$function$\n","function_name":"pipeline_editorial_validate_artifact_source()","table_name":"editorial_artifact_versions","tgname":"editorial_artifact_versions_source_trg"},{"definition":"CREATE TRIGGER editorial_version_status_events_append_only_trg BEFORE DELETE OR UPDATE ON editorial_version_status_events FOR EACH ROW EXECUTE FUNCTION pipeline_editorial_protect_append_only()","enabled":"O","function_definition":"CREATE OR REPLACE FUNCTION public.pipeline_editorial_protect_append_only()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\r\nBEGIN\r\n  RAISE EXCEPTION 'append-only editorial record cannot be changed';\r\nEND;\r\n$function$\n","function_name":"pipeline_editorial_protect_append_only()","table_name":"editorial_version_status_events","tgname":"editorial_version_status_events_append_only_trg"}]},"target_constraint_expected":"CHECK (artifact_type = ANY (ARRAY['article_dna'::text, 'silo_dna'::text, 'silo_page'::text, 'content_plan'::text, 'brand_dna'::text]))"}$brand_skills_baseline$, false) as configured
),
baseline as (
  select current_setting('minerador.brand_skills_baseline_json', true)::jsonb as value from baseline_set
),
target_constraint as (
  select pg_get_constraintdef(c.oid, true) as definition
  from pg_constraint c
  where c.conrelid = 'public.editorial_artifact_versions'::regclass
    and c.conname = 'editorial_artifact_versions_artifact_type_check'
),
column_rows as (
  select c.relname as table_name, a.attnum, a.attname::text as name, pg_catalog.format_type(a.atttypid, a.atttypmod) as type,
    a.attnotnull as not_null, pg_get_expr(ad.adbin, ad.adrelid) as default_expression, a.attidentity::text as identity, a.attgenerated::text as generated
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
  left join pg_attrdef ad on ad.adrelid = a.attrelid and ad.adnum = a.attnum
  where n.nspname = 'public' and c.relname in ('editorial_artifact_versions', 'editorial_version_status_events')
),
constraint_rows as (
  select cl.relname as table_name, c.conname, c.contype::text as type, pg_get_constraintdef(c.oid, true) as definition,
    c.convalidated, c.condeferrable, c.condeferred
  from pg_constraint c join pg_class cl on cl.oid = c.conrelid join pg_namespace n on n.oid = cl.relnamespace
  where n.nspname = 'public' and cl.relname in ('editorial_artifact_versions', 'editorial_version_status_events')
),
index_rows as (
  select c.relname as table_name, i.relname as index_name, pg_get_indexdef(i.oid) as definition
  from pg_index x join pg_class c on c.oid = x.indrelid join pg_class i on i.oid = x.indexrelid join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname in ('editorial_artifact_versions', 'editorial_version_status_events')
),
trigger_rows as (
  select c.relname as table_name, t.tgname, t.tgenabled::text as enabled, pg_get_triggerdef(t.oid, true) as definition,
    p.oid::regprocedure::text as function_name, pg_get_functiondef(p.oid) as function_definition
  from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace join pg_proc p on p.oid = t.tgfoid
  where not t.tgisinternal and n.nspname = 'public' and c.relname in ('editorial_artifact_versions', 'editorial_version_status_events')
),
rls_rows as (
  select c.relname as table_name, c.relrowsecurity as enabled, c.relforcerowsecurity as forced
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname in ('editorial_artifact_versions', 'editorial_version_status_events')
),
policy_rows as (
  select p.tablename as table_name, p.policyname, p.cmd, p.roles::text[] as roles, p.permissive, p.qual as using_expression, p.with_check as with_check_expression
  from pg_policies p where p.schemaname = 'public' and p.tablename in ('editorial_artifact_versions', 'editorial_version_status_events')
),
owner_rows as (
  select c.relname as table_name, r.rolname as owner
  from pg_class c join pg_namespace n on n.oid = c.relnamespace join pg_roles r on r.oid = c.relowner
  where n.nspname = 'public' and c.relname in ('editorial_artifact_versions', 'editorial_version_status_events')
),
acl_rows as (
  select c.relname as table_name, coalesce(c.relacl::text[], array[]::text[]) as acl
  from pg_class c join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public' and c.relname in ('editorial_artifact_versions', 'editorial_version_status_events')
),
count_rows as (select artifact_type, status, count(*)::bigint as count from public.editorial_artifact_versions group by artifact_type, status),
target_json as (select coalesce(jsonb_agg(to_jsonb(target_constraint) order by definition), '[]'::jsonb) as value from target_constraint),
columns_json as (select coalesce(jsonb_agg(to_jsonb(column_rows) order by table_name, attnum), '[]'::jsonb) as value from column_rows),
constraints_json as (select coalesce(jsonb_agg(to_jsonb(constraint_rows) order by table_name, conname) filter (where conname <> 'editorial_artifact_versions_artifact_type_check'), '[]'::jsonb) as value from constraint_rows),
indexes_json as (select coalesce(jsonb_agg(to_jsonb(index_rows) order by table_name, index_name), '[]'::jsonb) as value from index_rows),
triggers_json as (select coalesce(jsonb_agg(to_jsonb(trigger_rows) order by table_name, tgname), '[]'::jsonb) as value from trigger_rows),
rls_json as (select coalesce(jsonb_agg(to_jsonb(rls_rows) order by table_name), '[]'::jsonb) as value from rls_rows),
policies_json as (select coalesce(jsonb_agg(to_jsonb(policy_rows) order by table_name, policyname), '[]'::jsonb) as value from policy_rows),
owners_json as (select coalesce(jsonb_agg(to_jsonb(owner_rows) order by table_name), '[]'::jsonb) as value from owner_rows),
acl_json as (select coalesce(jsonb_agg(to_jsonb(acl_rows) order by table_name), '[]'::jsonb) as value from acl_rows),
counts_json as (select coalesce(jsonb_agg(to_jsonb(count_rows) order by artifact_type, status), '[]'::jsonb) as value from count_rows),
current_snapshot as (
  select jsonb_build_object('target_constraints', target_json.value, 'columns', columns_json.value, 'constraints', constraints_json.value,
    'indexes', indexes_json.value, 'triggers', triggers_json.value, 'rls', rls_json.value, 'policies', policies_json.value,
    'owners', owners_json.value, 'acl', acl_json.value, 'artifact_counts', counts_json.value) as value
  from target_json, columns_json, constraints_json, indexes_json, triggers_json, rls_json, policies_json, owners_json, acl_json, counts_json
),
baseline_snapshot as (
  select jsonb_set(value->'snapshot', '{constraints}', coalesce((select jsonb_agg(item order by item->>'table_name', item->>'conname') from jsonb_array_elements(value#>'{snapshot,constraints}') item where item->>'conname' <> 'editorial_artifact_versions_artifact_type_check'), '[]'::jsonb)) as value
  from baseline
),
comparison as (
  select b.value as baseline_value, c.value as current_value,
    (select definition from target_constraint) as target_definition
  from baseline_snapshot b cross join current_snapshot c
)
select case when target_definition = 'CHECK (artifact_type = ANY (ARRAY[''article_dna''::text, ''silo_dna''::text, ''silo_page''::text, ''content_plan''::text, ''brand_dna''::text, ''brand_skill''::text]))'
      and md5((baseline_value - 'target_constraints')::text) = md5((current_value - 'target_constraints')::text)
      and (current_value#>'{artifact_counts}') = (baseline_value#>'{artifact_counts}')
      and not exists (select 1 from public.editorial_artifact_versions where artifact_type = 'brand_skill')
    then 'PASS' else 'FAIL' end as post_verifier_status,
  case when target_definition = 'CHECK (artifact_type = ANY (ARRAY[''article_dna''::text, ''silo_dna''::text, ''silo_page''::text, ''content_plan''::text, ''brand_dna''::text, ''brand_skill''::text]))' then 'PASS' else 'FAIL' end as target_constraint,
  case when md5((baseline_value - 'target_constraints')::text) = md5((current_value - 'target_constraints')::text) then 'PASS' else 'FAIL' end as non_target_structure,
  case when (current_value#>'{artifact_counts}') = (baseline_value#>'{artifact_counts}') then '0' else 'NON_ZERO' end as data_delta,
  not exists (select 1 from public.editorial_artifact_versions where artifact_type = 'brand_skill') as brand_skill_data_delta_zero,
  baseline_value->'fingerprints' as baseline_fingerprints
from comparison;
